const { SSMClient, GetParameterCommand } = require('@aws-sdk/client-ssm');

async function loadProductionSecrets() {
  if (process.env.NODE_ENV === 'production') {
    const ssmClient = new SSMClient({});

    const secrets = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
