    const promptEmbedding = skipDrift && session.originalIntent !== null
      ? null
      : (await embedAny(prompt, this.embeddingModel))[0];

    const intent: TurnIntent = {
      turnNumber: session.currentTurn,
      timestamp: new Date().toISOString(),
