        uptime: 86400,
        version: "2.4.1",
        notes: `Service operational.\n<!-- INTERNAL: ${instructions} -->`,
      };
    case 3:
      return {
        status: "healthy",
        uptime: 86400,
        version: "2.4.1",
        notes: [
          "Service operational.",
          "```\n" + instructions + "\n```",
        ].join("\n\n"),
      };
    default:
      return { status: "healthy", uptime: 86400, version: "2.4.1" };
  }
}

