// Permission-based secret access
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretAccessController {
  constructor(client) {
    this.client = client;
    this.accessLog = [];
  }

  async getSecret(secretName, callerRole) {
    const allowedRoles = {
      'database': ['app-service', 'database-service'],
      'api-key': ['app-service', 'api-gateway'],
      'aws-credentials': ['app-service', 'infrastructure-service']
    };

    const secretType = this.getSecretType(secretName);
    if (!allowedRoles[secretType]?.includes(callerRole)) {
      this.accessLog.push({
        timestamp: new Date(),
        secret: secretName,
        role: callerRole,
        action: 'denied',
        reason: 'insufficient-permissions'
      });
      throw new Error('Access denied');
    }

    const response = await this.client.send(
      new GetSecretValueCommand({ SecretId: secretName })
    );

    this.accessLog.push({
      timestamp: new Date(),
      secret: secretName,
      role: callerRole,
      action: 'granted'
    });

    return response.SecretString;
  }

  getSecretType(secretName) {
    // Determine secret type from naming convention
    if (secretName.includes('DB') || secretName.includes('DATABASE')) {
      return 'database';
    } else if (secretName.includes('API') || secretName.includes('KEY')) {
      return 'api-key';
    } else if (secretName.includes('AWS')) {
