// Secret rotation helper
class SecretRotator {
  constructor() {
    this.secrets = new Map();
  }

  rotate(secretName) {
    // Generate new secret
    const newSecret = crypto.randomBytes(32).toString('hex');
    this.secrets.set(secretName, {
      value: newSecret,
      rotatedAt: new Date()
    });
    return newSecret;
  }

  validate(secretName, value) {
    const stored = this.secrets.get(secretName);
    return stored && stored.value === value;
  }
}

